// The isometric sprite atlas generated by `npm run art` (scripts/art/build.ts).
import atlasUrl from '../../assets/iso/atlas.png';
import data from '../../assets/iso/atlas.json';
import type { BuildingType } from '../../game/defs';

export interface Frame {
  x: number;
  y: number;
  w: number;
  h: number;
  ax: number; // anchor inside the frame
  ay: number;
}

export interface BuildingArtMeta {
  frames: number;
  fps: number;
  height: number;
  glow: boolean[];
  points: Record<string, [number, number][]>;
}

// Scenery around the map: footprint in tiles, animation, and whether it is too tall to stand in front of the map.
export interface DecorArtMeta {
  w: number;
  d: number;
  frames: number;
  fps: number;
  tall: boolean;
}

// A city theme (0.7, increment 2), by theme name ('rust', 'neon', 'green', 'corp'):
//   terrain  the terrain families with a themed twin: t/<theme>/<family>/... for t/<family>/... (same size, anchor)
//   scenery  the theme's own border scenery, frames sc/<theme>/<name>/<f> (+ /g glow), metadata like decorArt's
//   decor    the existing d/<name> scenery that suits the theme, to mix into its border ring
//   light    a suggested light: day = multiply colour (255 = unchanged), night = the night veil's colour (the
//            game's own is 16, 12, 52), dark = factor on the veil's opacity
export interface ThemeArtMeta {
  terrain: string[];
  scenery: Record<string, DecorArtMeta>;
  decor: string[];
  light: { day: [number, number, number]; night: [number, number, number]; dark: number };
}

type RawFrame = [number, number, number, number, number, number];
const raw = data as unknown as {
  w: number;
  h: number;
  frames: Record<string, RawFrame>;
  buildings: Record<BuildingType, BuildingArtMeta>;
  decor?: Record<string, DecorArtMeta>;
  variants?: Record<string, BuildingArtMeta>;
  themes?: Record<string, ThemeArtMeta>;
};

const frames = new Map<string, Frame>();
for (const [name, [x, y, w, h, ax, ay]] of Object.entries(raw.frames)) frames.set(name, { x, y, w, h, ax, ay });

export const buildingArt = raw.buildings;
export const decorArt = raw.decor ?? {};

// Buildings with modules installed (0.7): the same metadata as buildingArt, by variant name, e.g.
// 'dock+dockStorage', whose frames are b/<variant>/w<f>, b/<variant>/off (+ /g glow) and b/<variant>/shadow.
export const variantArt: Record<string, BuildingArtMeta> = raw.variants ?? {};

// The variant name for a building type and its installed modules: the type alone without modules, otherwise
// the type and the modules sorted, joined by '+' (the art pipeline's naming, scripts/art/models/modules.ts).
export function variantKey(type: BuildingType, modules?: readonly string[]): string {
  return modules && modules.length ? [type, ...[...modules].sort()].join('+') : type;
}

// City themes (see ThemeArtMeta). Scrapbot City has none and keeps the plain frames.
export const themeArt: Record<string, ThemeArtMeta> = raw.themes ?? {};

// The terrain frame to paint for a city theme: t/<theme>/<rest> when the theme has a twin of t/<rest>, otherwise the
// frame itself (no theme, or a frame every city shares: sludge, floors, bases, junk, rubble, lamps).
export function themedFrame(name: string, theme?: string | null): string {
  if (!theme || !name.startsWith('t/')) return name;
  const twin = `t/${theme}/${name.slice(2)}`;
  return frames.has(twin) ? twin : name;
}

// how many citizen looks the atlas has (cit/<variant>/sw/0)
export function citizenVariants(): number {
  let n = 0;
  while (frames.has(`cit/${n}/sw/0`)) n++;
  return n;
}

export function frame(name: string): Frame | undefined {
  return frames.get(name);
}

export function hasFrame(name: string): boolean {
  return frames.has(name);
}

let image: HTMLImageElement | null = null;
let alpha: Uint8Array | null = null;
let ready = false;
const waiters: (() => void)[] = [];

export function atlasImage(): HTMLImageElement | null {
  return ready ? image : null;
}

export function atlasReady(): boolean {
  return ready;
}

export function whenAtlasReady(fn: () => void): void {
  if (ready) fn();
  else waiters.push(fn);
}

// Starts loading at import time; the image is inlined in the build, so this takes a few milliseconds.
if (typeof Image !== 'undefined') {
  image = new Image();
  image.onload = () => {
    try {
      const c = document.createElement('canvas');
      c.width = raw.w;
      c.height = raw.h;
      const ctx = c.getContext('2d', { willReadFrequently: true });
      if (ctx) {
        ctx.drawImage(image!, 0, 0);
        const px = ctx.getImageData(0, 0, raw.w, raw.h).data;
        alpha = new Uint8Array(raw.w * raw.h);
        for (let i = 0; i < alpha.length; i++) alpha[i] = px[i * 4 + 3];
      }
    } catch {
      alpha = null; // picking falls back to the frame rectangle
    }
    ready = true;
    for (const fn of waiters.splice(0)) fn();
  };
  image.src = atlasUrl;
}

// Is the pixel (fx, fy) of a frame opaque? Used to click on what you actually see.
export function opaqueAt(f: Frame, fx: number, fy: number): boolean {
  if (fx < 0 || fy < 0 || fx >= f.w || fy >= f.h) return false;
  if (!alpha) return true;
  return alpha[(f.y + fy) * raw.w + f.x + fx] > 0;
}
